WITH windows AS (SELECT 0 AS sample, 28205 AS pid, 17222160000000 AS start_ns, 17224462878749 AS end_ns UNION ALL SELECT 1 AS sample, 28205 AS pid, 17225369999999 AS start_ns, 17227616487541 AS end_ns UNION ALL SELECT 2 AS sample, 28205 AS pid, 17228419999999 AS start_ns, 17230675799039 AS end_ns UNION ALL SELECT 3 AS sample, 28205 AS pid, 17231560000000 AS start_ns, 17233807924167 AS end_ns UNION ALL SELECT 4 AS sample, 28205 AS pid, 17234630000000 AS start_ns, 17236880105666 AS end_ns UNION ALL SELECT 5 AS sample, 28205 AS pid, 17237710000000 AS start_ns, 17239958390541 AS end_ns UNION ALL SELECT 6 AS sample, 28205 AS pid, 17240750000000 AS start_ns, 17243005771166 AS end_ns UNION ALL SELECT 7 AS sample, 28205 AS pid, 17243790000000 AS start_ns, 17246046831541 AS end_ns UNION ALL SELECT 8 AS sample, 28205 AS pid, 17246950000000 AS start_ns, 17249233409500 AS end_ns UNION ALL SELECT 9 AS sample, 28205 AS pid, 17250150000000 AS start_ns, 17252413668166 AS end_ns UNION ALL SELECT 10 AS sample, 28205 AS pid, 17253240000000 AS start_ns, 17255496690749 AS end_ns UNION ALL SELECT 11 AS sample, 28205 AS pid, 17256490000000 AS start_ns, 17258747959290 AS end_ns UNION ALL SELECT 12 AS sample, 28205 AS pid, 17259540000000 AS start_ns, 17261798274917 AS end_ns UNION ALL SELECT 13 AS sample, 28205 AS pid, 17262550000000 AS start_ns, 17264795279624 AS end_ns UNION ALL SELECT 14 AS sample, 28205 AS pid, 17265480000000 AS start_ns, 17267740925083 AS end_ns UNION ALL SELECT 15 AS sample, 28205 AS pid, 17268650000000 AS start_ns, 17270929499209 AS end_ns UNION ALL SELECT 16 AS sample, 28205 AS pid, 17271759999999 AS start_ns, 17274028749874 AS end_ns UNION ALL SELECT 17 AS sample, 28205 AS pid, 17274880000000 AS start_ns, 17277138132749 AS end_ns UNION ALL SELECT 18 AS sample, 28205 AS pid, 17277960000000 AS start_ns, 17280226989791 AS end_ns UNION ALL SELECT 19 AS sample, 28205 AS pid, 17281180000000 AS start_ns, 17283432542167 AS end_ns UNION ALL SELECT 20 AS sample, 28205 AS pid, 17284310000000 AS start_ns, 17286573053333 AS end_ns UNION ALL SELECT 21 AS sample, 28205 AS pid, 17287640000000 AS start_ns, 17289887477249 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample